'use strict'
/**
 * Evidence source of a honeypot session (docs/QLEARNING_EVIDENCE.md). It decides how a session counts as
 * learning evidence; it never changes detection, scoring or blocking.
 *
 *   operator   generated by the project's own operators (source in SENTINEL_OPERATOR_SOURCES, IPs or CIDRs)
 *   simulated  produced by a simulator or demo script (session id prefixed demo- / arena- / sim-)
 *   external   an independent party, ONLY when collection is authorised: HONEYPOT_EXTERNAL_COLLECTION=authorized
 *              and a published notice reference in HONEYPOT_COLLECTION_NOTICE (consent / legal basis)
 *   unknown    everything else (the default; never counted as independent evidence)
 * An admin can correct a label (PATCH /api/honeypot/sessions/:id/evidence-source, audited); automatic
 * classification never upgrades a session to "external" without the authorisation settings above.
 */
const net = require('net')

const EVIDENCE_SOURCES = ['operator', 'external', 'simulated', 'unknown']
const SIMULATED_PREFIX = /^(demo|arena|sim)-/i

function cidrList(raw) {
  const list = new net.BlockList()
  let any = false
  for (const entry of String(raw || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)) {
    const [addr, prefix] = entry.split('/')
    const fam = net.isIP(addr)
    if (!fam) continue
    const type = fam === 6 ? 'ipv6' : 'ipv4'
    if (prefix === undefined) list.addAddress(addr, type)
    else if (/^\d{1,3}$/.test(prefix)) list.addSubnet(addr, Number(prefix), type)
    else continue
    any = true
  }
  return any ? list : null
}

function externalCollectionAuthorized(env = process.env) {
  return (
    env.HONEYPOT_EXTERNAL_COLLECTION === 'authorized' && Boolean(String(env.HONEYPOT_COLLECTION_NOTICE || '').trim())
  )
}

/** Automatic label for a new session. Pure function of its inputs. */
function classifySession({ sessionId, sourceIP }, env = process.env) {
  if (SIMULATED_PREFIX.test(String(sessionId || ''))) return 'simulated'
  const ops = cidrList(env.SENTINEL_OPERATOR_SOURCES)
  const fam = net.isIP(String(sourceIP || ''))
  if (ops && fam && ops.check(sourceIP, fam === 6 ? 'ipv6' : 'ipv4')) return 'operator'
  if (fam && externalCollectionAuthorized(env)) return 'external'
  return 'unknown'
}

module.exports = { EVIDENCE_SOURCES, classifySession, externalCollectionAuthorized }
